declare changes jsonb=$data$[{"peak_slug":"babia-gora","expected_trail":{"id":27,"peak_id":17,"slug":"babia-gora-katalog-03","start_point_name":"Markowe Szczawiny","end_point_name":"Babia G\u00f3ra \u2013 Diablak"},"before":{"access":[{"row":{"id":23,"trail_id":27,"address":null,"postcode":null,"latitude":null,"longitude":null,"google_maps_url":"https://malopolska.szlaki.pttk.pl/320-pttk-malopolska-glowny-szlak-beskidzki","public_transport_url":null,"source_url":"https://bgpn.gov.pl/komunikat-turystyczny","last_verified_at":"2026-11-22T00:00:00+00:00","active":true,"created_at":"2026-11-22T19:10:42.626683+00:00"},"i18n":[{"lang":"en","warnings":"Check the weather, trail conditions and local restrictions before setting off. This record does not confirm that the route is currently open. Keep forest roads and emergency access clear.\nCheck the park notice and ticket rules before setting off. A trail entry ticket and parking payment are separate matters. Park information: https://bgpn.gov.pl/komunikat-turystyczny Tickets: https://bgpn.gov.pl/informacje-o-biletach","access_id":23,"directions":"The recorded walking segment starts at Markowe Szczawiny and ends at Babia G\u00f3ra \u2013 Diablak. The map link shows the hiking route; it does not establish vehicle access or legal parking.\nThe GPX starts at Markowe Szczawiny hut and runs via Prze\u0142\u0119cz Brona. It does not record the approach from parking or the Per\u0107 Akademik\u00f3w variant.\nThis is the start of a mountain walking segment. Add the approach and the descent to a settlement separately; do not use this point as a driving destination.","public_transport":"A current service to this route start has not been confirmed. Check the timetable for your travel date and plan the return."},{"lang":"pl","warnings":"Sprawd\u017a prognoz\u0119, stan szlaku i lokalne zakazy przed wyj\u015bciem. Opis nie potwierdza bie\u017c\u0105cego otwarcia trasy. Nie blokuj dr\u00f3g le\u015bnych ani dojazdu s\u0142u\u017cb ratowniczych.\nSprawd\u017a komunikat parku i zasady bilet\u00f3w przed wyj\u015bciem. Bilet wst\u0119pu na szlak i op\u0142ata parkingowa to odr\u0119bne sprawy. Informacje parku: https://bgpn.gov.pl/komunikat-turystyczny Bilety: https://bgpn.gov.pl/informacje-o-biletach","access_id":23,"directions":"Pocz\u0105tek opisanego odcinka: Markowe Szczawiny. Koniec: Babia G\u00f3ra \u2013 Diablak. Link do mapy pokazuje tras\u0119 piesz\u0105; nie potwierdza dojazdu samochodem ani legalnego parkingu.\nGPX rozpoczyna si\u0119 przy schronisku Markowe Szczawiny i prowadzi przez Prze\u0142\u0119cz Brona. Nie jest zapisem doj\u015bcia od parkingu ani wariantem Perci\u0105 Akademik\u00f3w.\nTo pocz\u0105tek wysoko po\u0142o\u017conego odcinka pieszego. Doj\u015bcie do niego oraz zej\u015bcie do miejscowo\u015bci trzeba doliczy\u0107 osobno; nie prowad\u017a nawigacji samochodowej do tego punktu.","public_transport":"Nie potwierdzono aktualnego po\u0142\u0105czenia do pocz\u0105tku tej trasy. Sprawd\u017a rozk\u0142ad na dzie\u0144 wycieczki i zaplanuj powr\u00f3t."},{"lang":"ua","warnings":"\u041f\u0435\u0440\u0435\u0434 \u0432\u0438\u0445\u043e\u0434\u043e\u043c \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0433\u043e\u0434\u0443, \u0441\u0442\u0430\u043d \u0441\u0442\u0435\u0436\u043a\u0438 \u0439 \u043c\u0456\u0441\u0446\u0435\u0432\u0456 \u043e\u0431\u043c\u0435\u0436\u0435\u043d\u043d\u044f. \u0426\u0435\u0439 \u043e\u043f\u0438\u0441 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454, \u0449\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u0437\u0430\u0440\u0430\u0437 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u0438\u0439. \u041d\u0435 \u043f\u0435\u0440\u0435\u043a\u0440\u0438\u0432\u0430\u0439\u0442\u0435 \u043b\u0456\u0441\u043e\u0432\u0456 \u0434\u043e\u0440\u043e\u0433\u0438 \u0439 \u043f\u0440\u043e\u0457\u0437\u0434 \u0440\u044f\u0442\u0443\u0432\u0430\u043b\u044c\u043d\u0438\u043a\u0456\u0432.\n\u041f\u0435\u0440\u0435\u0434 \u0432\u0438\u0445\u043e\u0434\u043e\u043c \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u043f\u0430\u0440\u043a\u0443 \u0439 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u043a\u0432\u0438\u0442\u043a\u0456\u0432. \u0412\u0445\u0456\u0434\u043d\u0438\u0439 \u043a\u0432\u0438\u0442\u043e\u043a \u043d\u0430 \u0441\u0442\u0435\u0436\u043a\u0443 \u0439 \u043e\u043f\u043b\u0430\u0442\u0430 \u043f\u0430\u0440\u043a\u043e\u0432\u043a\u0438 \u2014 \u043e\u043a\u0440\u0435\u043c\u0456 \u043f\u0438\u0442\u0430\u043d\u043d\u044f. \u0406\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044f \u043f\u0430\u0440\u043a\u0443: https://bgpn.gov.pl/komunikat-turystyczny \u041a\u0432\u0438\u0442\u043a\u0438: https://bgpn.gov.pl/informacje-o-biletach","access_id":23,"directions":"\u041e\u043f\u0438\u0441\u0430\u043d\u0438\u0439 \u043f\u0456\u0448\u0438\u0439 \u0432\u0456\u0434\u0440\u0456\u0437\u043e\u043a \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u044c\u0441\u044f \u0432 Markowe Szczawiny \u0456 \u0437\u0430\u043a\u0456\u043d\u0447\u0443\u0454\u0442\u044c\u0441\u044f \u0432 Babia G\u00f3ra \u2013 Diablak. \u041f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f \u043f\u043e\u043a\u0430\u0437\u0443\u0454 \u043f\u0456\u0448\u0438\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442, \u0430 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u0438\u0439 \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0456\u043b\u044c\u043d\u0438\u0439 \u043f\u0456\u0434\u2019\u0457\u0437\u0434 \u0447\u0438 \u0434\u043e\u0437\u0432\u043e\u043b\u0435\u043d\u0443 \u043f\u0430\u0440\u043a\u043e\u0432\u043a\u0443.\nGPX \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u044c\u0441\u044f \u0431\u0456\u043b\u044f \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u0443 Markowe Szczawiny \u0439 \u0432\u0435\u0434\u0435 \u0447\u0435\u0440\u0435\u0437 Prze\u0142\u0119cz Brona. \u0412\u0456\u043d \u043d\u0435 \u043c\u0456\u0441\u0442\u0438\u0442\u044c \u043f\u0456\u0434\u0445\u043e\u0434\u0443 \u0432\u0456\u0434 \u043f\u0430\u0440\u043a\u043e\u0432\u043a\u0438 \u0439 \u043d\u0435 \u0454 \u0432\u0430\u0440\u0456\u0430\u043d\u0442\u043e\u043c Per\u0107 Akademik\u00f3w.\n\u0426\u0435 \u043f\u043e\u0447\u0430\u0442\u043e\u043a \u0433\u0456\u0440\u0441\u044c\u043a\u043e\u0433\u043e \u043f\u0456\u0448\u043e\u0433\u043e \u0432\u0456\u0434\u0440\u0456\u0437\u043a\u0430. \u041e\u043a\u0440\u0435\u043c\u043e \u0432\u0440\u0430\u0445\u0443\u0439\u0442\u0435 \u043f\u0456\u0434\u0445\u0456\u0434 \u0456 \u0441\u043f\u0443\u0441\u043a \u0434\u043e \u043d\u0430\u0441\u0435\u043b\u0435\u043d\u043e\u0433\u043e \u043f\u0443\u043d\u043a\u0442\u0443; \u043d\u0435 \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u0439\u0442\u0435 \u0446\u044e \u0442\u043e\u0447\u043a\u0443 \u0434\u043b\u044f \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0456\u043b\u044c\u043d\u043e\u0457 \u043d\u0430\u0432\u0456\u0433\u0430\u0446\u0456\u0457.","public_transport":"\u0410\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0435 \u0441\u043f\u043e\u043b\u0443\u0447\u0435\u043d\u043d\u044f \u0434\u043e \u043f\u043e\u0447\u0430\u0442\u043a\u0443 \u0446\u044c\u043e\u0433\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043e. \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0440\u043e\u0437\u043a\u043b\u0430\u0434 \u043d\u0430 \u0434\u0435\u043d\u044c \u043f\u043e\u0434\u043e\u0440\u043e\u0436\u0456 \u0439 \u0441\u043f\u043b\u0430\u043d\u0443\u0439\u0442\u0435 \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f."},{"lang":"zh","warnings":"\u51fa\u53d1\u524d\u8bf7\u67e5\u770b\u5929\u6c14\u3001\u8def\u51b5\u548c\u5f53\u5730\u9650\u5236\u3002\u672c\u6761\u76ee\u4e0d\u4fdd\u8bc1\u8def\u7ebf\u5f53\u524d\u5f00\u653e\u3002\u8bf7\u52ff\u5835\u585e\u6797\u9053\u6216\u6551\u63f4\u901a\u9053\u3002\n\u51fa\u53d1\u524d\u8bf7\u67e5\u770b\u516c\u56ed\u516c\u544a\u53ca\u95e8\u7968\u89c4\u5b9a\u3002\u6b65\u9053\u95e8\u7968\u4e0e\u505c\u8f66\u8d39\u662f\u4e24\u9879\u4e0d\u540c\u4e8b\u9879\u3002\u516c\u56ed\u4fe1\u606f\uff1ahttps://bgpn.gov.pl/komunikat-turystyczny \u95e8\u7968\uff1ahttps://bgpn.gov.pl/informacje-o-biletach","access_id":23,"directions":"\u6240\u5217\u5f92\u6b65\u8def\u6bb5\u4eceMarkowe Szczawiny\u5f00\u59cb\uff0c\u5230Babia G\u00f3ra \u2013 Diablak\u7ed3\u675f\u3002\u5730\u56fe\u94fe\u63a5\u663e\u793a\u5f92\u6b65\u8def\u7ebf\uff0c\u5e76\u4e0d\u4ee3\u8868\u6c7d\u8f66\u53ef\u5230\u8fbe\u8d77\u70b9\u6216\u53ef\u5408\u6cd5\u505c\u8f66\u3002\nGPX\u4eceMarkowe Szczawiny\u5c71\u5c4b\u7ecfPrze\u0142\u0119cz Brona\u901a\u884c\uff0c\u4e0d\u5305\u542b\u4ece\u505c\u8f66\u573a\u4e0a\u5c71\u5c4b\u7684\u8def\u6bb5\uff0c\u4e5f\u4e0d\u662fPer\u0107 Akademik\u00f3w\u8def\u7ebf\u3002\n\u6b64\u5904\u662f\u5c71\u4e2d\u5f92\u6b65\u8def\u6bb5\u7684\u8d77\u70b9\u3002\u5230\u8fbe\u8d77\u70b9\u53ca\u4e0b\u5c71\u5230\u6751\u9547\u7684\u8def\u7a0b\u9700\u53e6\u8ba1\uff0c\u8bf7\u52ff\u5c06\u6b64\u70b9\u4f5c\u4e3a\u9a7e\u8f66\u76ee\u7684\u5730\u3002","public_transport":"\u5c1a\u672a\u6838\u5b9e\u524d\u5f80\u6b64\u8def\u7ebf\u8d77\u70b9\u7684\u73b0\u884c\u516c\u5171\u4ea4\u901a\u3002\u8bf7\u67e5\u8be2\u51fa\u884c\u5f53\u5929\u7684\u65f6\u523b\u8868\uff0c\u5e76\u5b89\u6392\u8fd4\u7a0b\u3002"}]}],"parking":[]},"parking":{"row":{"slug":"zawoja-markowa-bgpn","address":null,"postcode":null,"latitude":null,"longitude":null,"map_url":"https://www.google.com/maps/search/?api=1&query=Zawoja%20Markowa%20%E2%80%94%20parking%20BgPN","source_url":"https://bgpn.gov.pl/wejscia-i-parkingi","is_primary":false,"paid":true,"toilets":null,"overnight_allowed":null,"capacity":null,"last_verified_at":"2026-11-22T00:00:00Z","active":true},"i18n":{"pl":{"name":"Zawoja Markowa \u2014 parking BgPN","description":"Parking parku w Zawoi Markowej. Do schroniska Markowe Szczawiny prowadzi st\u0105d zielony szlak; doj\u015bcie do schroniska nie jest cz\u0119\u015bci\u0105 zapisanego GPX.","notes":"Sprawd\u017a aktualne oznakowanie i dost\u0119pno\u015b\u0107 przed wyjazdem. Link mapy wyszukuje nazw\u0119 miejsca, nie zweryfikowane stanowisko. Toalety, pojemno\u015b\u0107 i parkowanie noc\u0105 nie s\u0105 potwierdzone.","fee_info":"Aktualn\u0105 op\u0142at\u0119 i spos\u00f3b p\u0142atno\u015bci sprawd\u017a w regulaminie operatora.","opening_info":null},"en":{"name":"Zawoja Markowa \u2014 parking BgPN","description":"Park parking in Zawoja Markowa. A green trail leads to Markowe Szczawiny hut; that approach is outside the recorded GPX.","notes":"Check current signs and availability before travelling. The map searches the place name, not a surveyed bay. Toilets, capacity and overnight parking are unconfirmed.","fee_info":"Check the current fee and payment method in the operator\u2019s rules.","opening_info":null},"ua":{"name":"Zawoja Markowa \u2014 parking BgPN","description":"\u041f\u0430\u0440\u043a\u043e\u0432\u043a\u0430 \u043f\u0430\u0440\u043a\u0443 \u0432 Zawoja Markowa. \u0417\u0435\u043b\u0435\u043d\u0430 \u0441\u0442\u0435\u0436\u043a\u0430 \u0432\u0435\u0434\u0435 \u0434\u043e \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u0443 Markowe Szczawiny; \u0446\u0435\u0439 \u043f\u0456\u0434\u0445\u0456\u0434 \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442\u044c \u0434\u043e \u0437\u0430\u043f\u0438\u0441\u0430\u043d\u043e\u0433\u043e GPX.","notes":"\u041f\u0435\u0440\u0435\u0434 \u043f\u043e\u0457\u0437\u0434\u043a\u043e\u044e \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0456 \u0437\u043d\u0430\u043a\u0438 \u0439 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0456\u0441\u0442\u044c. \u041c\u0430\u043f\u0430 \u0448\u0443\u043a\u0430\u0454 \u043d\u0430\u0437\u0432\u0443 \u043c\u0456\u0441\u0446\u044f, \u0430 \u043d\u0435 \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0435\u043d\u0435 \u043f\u0430\u0440\u043a\u043e\u043c\u0456\u0441\u0446\u0435. \u0422\u0443\u0430\u043b\u0435\u0442\u0438, \u043c\u0456\u0441\u0442\u043a\u0456\u0441\u0442\u044c \u0456 \u043d\u0456\u0447\u043d\u0435 \u043f\u0430\u0440\u043a\u0443\u0432\u0430\u043d\u043d\u044f \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043e.","fee_info":"\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0443 \u043f\u043b\u0430\u0442\u0443 \u0439 \u0441\u043f\u043e\u0441\u0456\u0431 \u043e\u043f\u043b\u0430\u0442\u0438 \u0432 \u043f\u0440\u0430\u0432\u0438\u043b\u0430\u0445 \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430.","opening_info":null},"zh":{"name":"Zawoja Markowa \u2014 parking BgPN","description":"\u4f4d\u4e8eZawoja Markowa\u7684\u516c\u56ed\u505c\u8f66\u573a\uff0c\u53ef\u6cbf\u7eff\u8272\u6b65\u9053\u524d\u5f80Markowe Szczawiny\u5c71\u5c4b\uff1b\u6b64\u6bb5\u63a5\u8fd1\u8def\u7ebf\u672a\u5305\u542b\u5728\u6240\u5f55GPX\u4e2d\u3002","notes":"\u51fa\u884c\u524d\u8bf7\u6838\u5b9e\u73b0\u884c\u6807\u5fd7\u548c\u53ef\u7528\u60c5\u51b5\u3002\u5730\u56fe\u6309\u5730\u70b9\u540d\u79f0\u641c\u7d22\uff0c\u5e76\u975e\u7ecf\u6d4b\u91cf\u786e\u8ba4\u7684\u8f66\u4f4d\u3002\u536b\u751f\u95f4\u3001\u5bb9\u91cf\u53ca\u591c\u95f4\u505c\u8f66\u8bb8\u53ef\u5c1a\u672a\u786e\u8ba4\u3002","fee_info":"\u8bf7\u67e5\u770b\u8fd0\u8425\u65b9\u73b0\u884c\u89c4\u5b9a\uff0c\u786e\u8ba4\u8d39\u7528\u53ca\u4ed8\u6b3e\u65b9\u5f0f\u3002","opening_info":null}}},"evidence_level":"operator","evidence":[{"key":"babia","url":"https://bgpn.gov.pl/wejscia-i-parkingi","resolved_url":"https://bgpn.gov.pl/wejscia-i-parkingi","status":200,"checked_on":"2026-11-22","sha256":"f3099e5305a9df44d5860bf94c75566d708dcd9512335b1424b95122674371ad"},{"key":"babia-approach","url":"https://malopolska.szlaki.pttk.pl/2589-pttk-malopolska-zawoja-markowa","resolved_url":"https://malopolska.szlaki.pttk.pl/2589-pttk-malopolska-zawoja-markowa","status":200,"checked_on":"2026-11-22","sha256":"5954a4e445fe8f6f554074